package com.hasibul.megh;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import android.app.job.*;import org.json.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 WebView web;ExecutorService executor=Executors.newSingleThreadExecutor();
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xfff6fafc);getWindow().setNavigationBarColor(0xfff6fafc);web=new WebView(this);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.addJavascriptInterface(new Bridge(),"MeghNative");web.setWebViewClient(new WebViewClient(){public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){if("https".equals(r.getUrl().getScheme())&&"appassets.androidplatform.net".equals(r.getUrl().getHost())){try{String path=r.getUrl().getPath();if(path==null)throw new java.io.IOException();String asset=path.equals("/index.html")?"index.html":path.startsWith("/themes/")&&!path.contains("..")?path.substring(1):null;if(asset==null)throw new java.io.IOException();String mime=asset.endsWith(".png")?"image/png":asset.endsWith(".webp")?"image/webp":asset.endsWith(".jpg")?"image/jpeg":"text/html";return new WebResourceResponse(mime,mime.equals("text/html")?"UTF-8":null,getAssets().open(asset));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",java.util.Collections.emptyMap(),new java.io.ByteArrayInputStream(new byte[0]));}}return new WebResourceResponse("text/plain","UTF-8",new java.io.ByteArrayInputStream(new byte[0]));}});web.loadUrl("https://appassets.androidplatform.net/index.html");}
 class Bridge {
 @JavascriptInterface public void weather(double lat,double lon){if(!Double.isFinite(lat)||!Double.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return;getSharedPreferences("megh",0).edit().putString("lat",""+lat).putString("lon",""+lon).apply();executor.execute(()->{try{String data=Weather.fetch(lat,lon);getSharedPreferences("megh",0).edit().putString("weather",data).putLong("updated",System.currentTimeMillis()).apply();MeghWidget.refresh(MainActivity.this);runOnUiThread(()->web.evaluateJavascript("receiveWeather("+JSONObject.quote(data)+")",null));}catch(Exception e){runOnUiThread(()->web.evaluateJavascript("weatherError()",null));}});}
 @JavascriptInterface public void preferences(String lang,String theme,String city){getSharedPreferences("megh",0).edit().putString("lang",lang).putString("theme",theme).putString("city",city).apply();MeghWidget.refresh(MainActivity.this);}
 @JavascriptInterface public void notifications(boolean enabled){getSharedPreferences("megh",0).edit().putBoolean("alerts",enabled).apply();runOnUiThread(()->{JobScheduler s=getSystemService(JobScheduler.class);if(!enabled){s.cancel(7);return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);s.schedule(new JobInfo.Builder(7,new ComponentName(MainActivity.this,WeatherJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(3*60*60*1000).setPersisted(true).build());});}
 }
 public void onDestroy(){executor.shutdownNow();web.removeJavascriptInterface("MeghNative");web.destroy();super.onDestroy();}
}
